    matToolBlocks: $('matToolBlocks'),
    matTextWrap: $('matTextWrap'),
    matTextDetect: $('matTextDetect'),
    matZoomStage: $('matZoomStage'),
    matZoomBar: $('matZoomBar'),
    matZoomLabel: $('matZoomLabel'),
    matZoomIn: $('matZoomIn'),
    matZoomOut: $('matZoomOut'),
